10.2 Is there an unnamed gene model that behaves like AR?
If the EGAPx AR model is broken, the real AR reads may have landed on an unnamed egapxtmp_* model. This is not a substitute for a sequence-level check, but a co-expression scan is cheap and can nominate candidates: a true AR model should be expressed, and should respond to flutamide in a similar way to known AR-responsive genes.


Code
## Genes with a known androgen connection that ARE detected here, used as a bait set.
bait &lt;- ar_ids$gene_id[ar_ids$gene_name %in%
                         c("SRD5A1", "SRD5A2", "CYP17A1", "NR3C1", "FOXO1")]

if (length(bait) &gt;= 2) {

  vmat &lt;- assay(vsd)
  bait_profile &lt;- colMeans(vmat[bait, , drop = FALSE])

  ## correlate every gene against the mean bait profile
  cors &lt;- cor(t(vmat), bait_profile, method = "spearman")

  ar_candidates &lt;- tibble(
    gene_id = rownames(vmat),
    rho     = as.numeric(cors)
  ) |&gt;
    left_join(gene_annot, by = "gene_id") |&gt;
    filter(grepl("^egapxtmp_", gene_name) | is.na(gene_name)) |&gt;
    arrange(desc(rho)) |&gt;
    head(25) |&gt;
    left_join(
      res_body_flu |&gt; select(gene_id, flu_body_LFC = log2FoldChange, flu_body_padj = padj),
      by = "gene_id"
    )

  write_csv(ar_candidates, file.path(OUT_DIR, "tables", "unnamed_genes_correlated_with_androgen_bait.csv"))
  knitr::kable(ar_candidates, digits = 3,
               caption = paste("Unnamed gene models most correlated with the detected",
                               "androgen-pathway bait set. Candidates only — confirm by",
                               "aligning the model's sequence to a known AR protein."))
} else {
  cat("Too few detected bait genes for a co-expression scan.\n")
}

14 10. Functional enrichment
The S. parvus EGAPx annotation carries uppercase gene symbols for a subset of models; the remainder are egapxtmp_* placeholders with no symbol. Enrichment is therefore run by treating those symbols as human orthologue proxies against org.Hs.eg.db.
Symbols recovered in Section 9d are folded in here, keyed on gene_id, and only ever fill a gap, an EGAPx-assigned symbol is never overwritten. If Section 9d was skipped, enrichment runs on EGAPx symbols alone. The recovery is a modest widening of the input rather than a transformation of it; Section 9d quantifies exactly how modest, and why the remainder needs sequence-based orthology instead.






NoteWhat this does and does not license



Symbol-based orthology is an approximation. A frog gene named AR is presumed to be the orthologue of human AR, which is reasonable for conserved, well-named genes and unreliable for rapidly evolving families and one-to-many relationships. Crucially, the ~50% of the annotation with no symbol is invisible to this analysis, so an unenriched term may simply mean its genes were unnamed. The universe is restricted to tested, symbol-bearing genes so the background matches the foreground. Use these terms to generate hypotheses, not as evidence on their own.




Code
has_cp &lt;- requireNamespace("clusterProfiler", quietly = TRUE) &&
          requireNamespace("org.Hs.eg.db", quietly = TRUE)

if (!has_cp) {
  cat("clusterProfiler / org.Hs.eg.db not installed — enrichment skipped.\n",
      "Install with:\n",
      '  BiocManager::install(c("clusterProfiler", "org.Hs.eg.db"))\n')
} else {
  suppressPackageStartupMessages({
    library(clusterProfiler)
    library(org.Hs.eg.db)
  })
}

## IMPORTANT: clusterProfiler / AnnotationDbi export their own `select()` and `filter()`,
## which mask the dplyr versions once those packages are attached. Every dplyr verb used
## after this point is therefore called explicitly via dplyr:: to keep the pipelines working.
select &lt;- dplyr::select
filter &lt;- dplyr::filter
rename &lt;- dplyr::rename
mutate &lt;- dplyr::mutate
slice_min &lt;- dplyr::slice_min

## a symbol is "usable" if it is not an egapxtmp placeholder and not a tRNA model
is_real_symbol &lt;- function(x) {
  !is.na(x) & x != "" & !grepl("^egapxtmp_", x) & !grepl("^trn", x, ignore.case = TRUE)
}

## ---- fold in the symbols recovered in Section 9d ---------------------------
## §9d validated a description-to-symbol join at &gt;99.9% precision, so those symbols
## are used here to widen the enrichment input. Recovery is keyed on gene_id, never
## on the display name, and it only ever FILLS a missing symbol - an EGAPx symbol is
## never overwritten. If §9d did not run, this is a no-op and enrichment behaves
## exactly as it did before.
RECOVERED_SYM &lt;- if (exists("symbol_map")) {
  m &lt;- symbol_map |&gt;
    dplyr::filter(!is.na(recovered_symbol), is.na(egapx_symbol))
  setNames(m$recovered_symbol, m$gene_id)
} else character(0)

add_recovered &lt;- function(res_df) {
  if (!length(RECOVERED_SYM) || !"gene_id" %in% names(res_df)) return(res_df)
  hit &lt;- !is_real_symbol(res_df$gene_name) & res_df$gene_id %in% names(RECOVERED_SYM)
  res_df$gene_name[hit] &lt;- unname(RECOVERED_SYM[res_df$gene_id[hit]])
  res_df
}




Code
## Records why each contrast/direction produced (or failed to produce) enrichment,
## so that "no terms" is never indistinguishable from "silently errored".
enrich_log &lt;- list()

run_enrichment &lt;- function(res_df, label, ont = "BP") {

  if (!has_cp) return(NULL)
  res_df &lt;- add_recovered(res_df)

  universe_sym &lt;- res_df |&gt;
    filter(!is.na(padj), is_real_symbol(gene_name)) |&gt;
    pull(gene_name) |&gt; unique() |&gt; toupper()

  out &lt;- list()

  for (dir in c("up", "down")) {
    sig_sym &lt;- res_df |&gt;
      filter(!is.na(padj), padj &lt; ALPHA, is_real_symbol(gene_name),
             if (dir == "up") log2FoldChange &gt;=  LFC_CUTOFF
             else             log2FoldChange &lt;= -LFC_CUTOFF) |&gt;
      pull(gene_name) |&gt; unique() |&gt; toupper()

    enrich_log[[paste(label, dir)]] &lt;&lt;- data.frame(
      contrast = label, direction = dir,
      n_universe_symbols = length(universe_sym),
      n_query_symbols    = length(sig_sym)
    )

    if (length(sig_sym) &lt; 10) {
      message(sprintf("%s / %s: only %d symbol-bearing genes — skipped",
                      label, dir, length(sig_sym)))
      next
    }

    ego &lt;- tryCatch(
      clusterProfiler::enrichGO(
        gene          = sig_sym,
        universe      = universe_sym,
        OrgDb         = org.Hs.eg.db,
        keyType       = "SYMBOL",
        ont           = ont,
        pAdjustMethod = "BH",
        pvalueCutoff  = 0.05,
        qvalueCutoff  = 0.20,
        readable      = FALSE
      ), error = function(e) { message("enrichGO failed: ", conditionMessage(e)); NULL })

    if (is.null(ego) || nrow(as.data.frame(ego)) == 0) {
      message(sprintf("%s / %s: no enriched GO:%s terms", label, dir, ont))
      next
    }

    df &lt;- as.data.frame(ego) |&gt; mutate(contrast = label, direction = dir)
    write_csv(df, file.path(OUT_DIR, "enrichment",
                            paste0(label, "_", dir, "_GO", ont, ".csv")))
    out[[dir]] &lt;- df
  }

  if (length(out) == 0) return(NULL)
  bind_rows(out)
}

enrich_all &lt;- list(
  leg_emergence_body   = run_enrichment(res_body_dev, "leg_emergence_body"),
