14.1 GSEA: for contrasts with too few significant genes
Over-representation analysis needs a reasonably sized significant-gene list, which the AR-blockade contrasts do not have. GSEA sidesteps that: it ranks every tested gene and asks whether a pathway’s members sit preferentially at one end of the ranking. It therefore detects coordinated, individually-subthreshold shifts, the pattern most likely for a receptor-blockade experiment at this sample size.
Genes are ranked by the Wald statistic (log2FoldChange / lfcSE), which carries both direction and confidence.


Code
run_gsea &lt;- function(res_df, label, ont = "BP") {

  if (!has_cp) return(NULL)
  res_df &lt;- add_recovered(res_df)

  ranked &lt;- res_df |&gt;
    filter(!is.na(padj), !is.na(log2FoldChange), !is.na(lfcSE), lfcSE &gt; 0,
           is_real_symbol(gene_name)) |&gt;
    mutate(symbol = toupper(gene_name), stat = log2FoldChange / lfcSE) |&gt;
    group_by(symbol) |&gt;
    summarise(stat = stat[which.max(abs(stat))], .groups = "drop") |&gt;
    arrange(desc(stat))

  if (nrow(ranked) &lt; 100) return(NULL)

  gl &lt;- setNames(ranked$stat, ranked$symbol)

  ego &lt;- tryCatch(
    clusterProfiler::gseGO(geneList = gl, OrgDb = org.Hs.eg.db, keyType = "SYMBOL",
                           ont = ont, minGSSize = 15, maxGSSize = 500,
                           pvalueCutoff = 0.05, pAdjustMethod = "BH",
                           verbose = FALSE, seed = TRUE),
    error = function(e) { message("gseGO failed for ", label, ": ", conditionMessage(e)); NULL })

  if (is.null(ego)) return(NULL)
  d &lt;- as.data.frame(ego)
  if (nrow(d) == 0) { message(label, ": no significant GSEA terms"); return(NULL) }

  d &lt;- d |&gt; mutate(contrast = label,
                   direction = ifelse(NES &gt; 0, "enriched in numerator",
                                              "enriched in denominator"))
  write_csv(d, file.path(OUT_DIR, "enrichment", paste0(label, "_GSEA_GO", ont, ".csv")))
  d
}

