15 10b. Functional enrichment: direct GO annotation (eggNOG-mapper)
Section 10 treats every egapxtmp_* model that lacks a symbol as invisible: enrichGO() requires a human symbol to retrieve GO terms, so roughly half the expressed transcriptome never enters the query or the universe. eggNOG-mapper assigns GO terms directly from sequence orthology, bypassing the symbol requirement. This section re-runs enrichment using those terms via enricher() with a custom TERM2GENE table.
The annotations file (sparvus.emapper.annotations) must be copied to PROJECT_DIR before rendering. The section skips gracefully if it is absent.


Code
EGGNOG_FILE &lt;- file.path(PROJECT_DIR, "sparvus.emapper.annotations")

RUN_EGGNOG &lt;- file.exists(EGGNOG_FILE) &&
              has_cp &&
              requireNamespace("GO.db",         quietly = TRUE) &&
              requireNamespace("AnnotationDbi", quietly = TRUE)

if (!RUN_EGGNOG)
  message("Section 10b needs sparvus.emapper.annotations, clusterProfiler, and GO.db — skipping.")




Code
if (RUN_EGGNOG) {

  emapper &lt;- readr::read_tsv(EGGNOG_FILE, comment = "##",
                              na = c("", "-"), show_col_types = FALSE)
  ## the first column header is literally "#query" in emapper v2
  names(emapper)[1] &lt;- sub("^#", "", names(emapper)[1])

  ## extract egapxtmp_XXXXXX regardless of surrounding header text
  ## handles both "egapxtmp_043373-P2" and "gnl|WGS:ZZZZ|egapxtmp_043373-P2"
  emapper &lt;- dplyr::mutate(emapper,
                           gene_id = stringr::str_extract(query, "egapxtmp_\\d+"))

  n_na &lt;- sum(is.na(emapper$gene_id))
  if (n_na &gt; 0)
    warning(n_na, " query IDs did not match 'egapxtmp_\\d+'. Check head(emapper$query, 3).")

  ## one row per GO term per gene_id
  term2gene_all &lt;- emapper |&gt;
    dplyr::filter(!is.na(GOs)) |&gt;
    dplyr::mutate(go = strsplit(GOs, ",")) |&gt;
    tidyr::unnest(go) |&gt;
    dplyr::mutate(go = trimws(go)) |&gt;
    dplyr::select(go, gene_id) |&gt;
    dplyr::distinct()

  ## look up ontology class and term description for every GO ID seen
  go_info &lt;- AnnotationDbi::select(
      GO.db::GO.db,
      keys    = unique(term2gene_all$go),
      columns = c("TERM", "ONTOLOGY"),
      keytype = "GOID") |&gt;
    tibble::as_tibble() |&gt;
    dplyr::rename(go = GOID, term_name = TERM, ontology = ONTOLOGY) |&gt;
    dplyr::filter(!is.na(ontology))

  ## restrict to Biological Process (run MF/CC analogously if needed)
  term2gene_bp &lt;- dplyr::semi_join(
    term2gene_all,
    dplyr::filter(go_info, ontology == "BP"),
    by = "go")

  term2name_bp &lt;- go_info |&gt;
    dplyr::filter(ontology == "BP") |&gt;
    dplyr::select(go, term_name) |&gt;
    dplyr::distinct()

  cat("BP terms:", dplyr::n_distinct(term2gene_bp$go),
      "| gene-term pairs:", nrow(term2gene_bp), "\n")
}



