if (RUN_EGGNOG) {

  run_enrichment_eggnog &lt;- function(res_df, label) {

    out &lt;- list()

    for (dir in c("up", "down")) {

      universe_ids &lt;- res_df |&gt;
        dplyr::filter(!is.na(padj)) |&gt;
        dplyr::pull(gene_id) |&gt;
        intersect(unique(term2gene_bp$gene_id))

      sig_ids &lt;- res_df |&gt;
        dplyr::filter(
          !is.na(padj), padj &lt; ALPHA,
          if (dir == "up") log2FoldChange &gt;= LFC_CUTOFF
          else             log2FoldChange &lt;= -LFC_CUTOFF) |&gt;
        dplyr::pull(gene_id) |&gt;
        intersect(unique(term2gene_bp$gene_id))

      if (length(sig_ids) &lt; 5) {
        message(sprintf("%s / %s: %d genes with GO terms — skipped",
                        label, dir, length(sig_ids)))
        next
      }

      ego &lt;- tryCatch(
        clusterProfiler::enricher(
          gene          = sig_ids,
          universe      = universe_ids,
          TERM2GENE     = term2gene_bp,
          TERM2NAME     = term2name_bp,
          pAdjustMethod = "BH",
          pvalueCutoff  = 0.05,
          qvalueCutoff  = 0.20
        ),
        error = function(e) {
          message(sprintf("enricher failed (%s/%s): %s", label, dir, conditionMessage(e)))
          NULL
        })

      if (is.null(ego) || nrow(as.data.frame(ego)) == 0) {
        message(sprintf("%s / %s: no enriched BP terms", label, dir))
        next
      }

      df &lt;- dplyr::mutate(as.data.frame(ego), contrast = label, direction = dir)
      readr::write_csv(df,
        file.path(OUT_DIR, "enrichment",
                  paste0(label, "_", dir, "_eggnog_GOBP.csv")))

      out[[dir]] &lt;- list(result = ego, df = df)
    }

    out
  }

  enrich_eggnog &lt;- list(
    leg_emergence_body  = run_enrichment_eggnog(res_body_dev, "leg_emergence_body"),
    nervous_system_head = run_enrichment_eggnog(res_head_dev, "nervous_system_head"),
    AR_blockade_body    = run_enrichment_eggnog(res_body_flu, "AR_blockade_body"),
    AR_blockade_head    = run_enrichment_eggnog(res_head_flu, "AR_blockade_head"),
    old_tissue_adjusted = run_enrichment_eggnog(res_old_df,   "old_tissue_adjusted")
  )
  enrich_eggnog &lt;- enrich_eggnog[lengths(enrich_eggnog) &gt; 0]

  cat("Contrasts with at least one enriched direction:",
      length(enrich_eggnog), "\n")
}




