16.2 GSEA: GO Biological Process and KEGG
GSEA ranks all tested genes by their shrunken log2 fold change and tests whether genes annotated with each term cluster at the top or bottom of that list. It does not use a significance cutoff, making it more sensitive to coordinated pathway shifts where individual genes fall below the DE threshold.


Code
if (RUN_EXTRA) {

  ## Build a sorted named vector of shrunken LFCs for GSEA.
  ## NA LFCs (outliers, zero-count genes) are dropped; all remaining tested genes
  ## are included so the background is the full experiment, not just DE genes.
  make_ranks &lt;- function(res_df) {
    res_df |&gt;
      dplyr::filter(!is.na(log2FoldChange)) |&gt;
      dplyr::arrange(dplyr::desc(log2FoldChange)) |&gt;
      dplyr::select(gene_id, log2FoldChange) |&gt;
      dplyr::distinct(gene_id, .keep_all = TRUE) |&gt;
      tibble::deframe()
  }

  run_gsea &lt;- function(ranks, term2gene, term2name, label, suffix) {
    gs &lt;- tryCatch(
      clusterProfiler::GSEA(
        geneList      = ranks,
        TERM2GENE     = term2gene,
        TERM2NAME     = term2name,
        minGSSize     = 10,
        maxGSSize     = 500,
        pvalueCutoff  = 0.05,
        pAdjustMethod = "BH",
        eps           = 0,
        seed          = TRUE,
        verbose       = FALSE),
      error = function(e) {
        message(sprintf("GSEA failed (%s/%s): %s", label, suffix, conditionMessage(e)))
        NULL
      })

    if (is.null(gs) || nrow(as.data.frame(gs)) == 0) {
      message(sprintf("%s / %s: no significant GSEA terms", label, suffix))
      return(NULL)
    }

    df &lt;- dplyr::mutate(as.data.frame(gs), contrast = label, gene_set = suffix)
    readr::write_csv(df,
      file.path(OUT_DIR, "enrichment", paste0(label, "_GSEA_", suffix, ".csv")))
    gs
  }

  contrasts_list &lt;- list(
    leg_emergence_body  = res_body_dev,
    nervous_system_head = res_head_dev,
    AR_blockade_body    = res_body_flu,
    AR_blockade_head    = res_head_flu,
    old_tissue_adjusted = res_old_df
  )

  gsea_go   &lt;- lapply(names(contrasts_list), function(nm)
    run_gsea(make_ranks(contrasts_list[[nm]]), term2gene_bp,   term2name_bp,   nm, "GOBP"))
  gsea_kegg &lt;- lapply(names(contrasts_list), function(nm)
    run_gsea(make_ranks(contrasts_list[[nm]]), term2gene_kegg, term2name_kegg, nm, "KEGG"))

  names(gsea_go)   &lt;- names(contrasts_list)
  names(gsea_kegg) &lt;- names(contrasts_list)

  gsea_go   &lt;- gsea_go[!vapply(gsea_go,   is.null, logical(1))]
  gsea_kegg &lt;- gsea_kegg[!vapply(gsea_kegg, is.null, logical(1))]

  cat("GSEA GO results:   ", length(gsea_go),   "contrasts with significant terms\n")
  cat("GSEA KEGG results: ", length(gsea_kegg), "contrasts with significant terms\n")
}




