16.3 COG functional category profile
COG categories describe the broad functional class of each gene model. This is not a statistical enrichment test, it shows whether upregulated and downregulated genes are concentrated in particular functional classes compared with all tested genes.


Code
if (RUN_EXTRA) {

  COG_LABELS &lt;- c(
    A = "RNA processing", B = "Chromatin structure",
    C = "Energy metabolism", D = "Cell cycle / division",
    E = "Amino acid metabolism", F = "Nucleotide metabolism",
    G = "Carbohydrate metabolism", H = "Coenzyme metabolism",
    I = "Lipid metabolism", J = "Translation / ribosome",
    K = "Transcription", L = "DNA replication / repair",
    M = "Cell wall / membrane", N = "Cell motility",
    O = "Protein turnover / chaperones", P = "Ion transport / metabolism",
    Q = "Secondary metabolites", R = "General function only",
    S = "Function unknown", T = "Signal transduction",
    U = "Vesicular transport", V = "Defense mechanisms",
    W = "Extracellular structures", Z = "Cytoskeleton"
  )

  ## one row per COG letter per gene (a gene can have multiple letters)
  cog_genes &lt;- emapper |&gt;
    dplyr::filter(!is.na(COG_category), COG_category != "-") |&gt;
    dplyr::mutate(cog = strsplit(COG_category, "")) |&gt;
    tidyr::unnest(cog) |&gt;
    dplyr::filter(cog %in% names(COG_LABELS)) |&gt;
    dplyr::select(gene_id, cog) |&gt;
    dplyr::distinct()

  ## use AR_blockade_body as the representative contrast; swap for another if preferred
  focal &lt;- res_body_flu |&gt;
    dplyr::filter(!is.na(padj)) |&gt;
    dplyr::mutate(de_class = dplyr::case_when(
      padj &lt; ALPHA & log2FoldChange &gt;=  LFC_CUTOFF ~ "up",
      padj &lt; ALPHA & log2FoldChange &lt;= -LFC_CUTOFF ~ "down",
      TRUE ~ "background"))

  cog_counts &lt;- cog_genes |&gt;
    dplyr::inner_join(focal |&gt; dplyr::select(gene_id, de_class), by = "gene_id") |&gt;
    dplyr::count(cog, de_class) |&gt;
    dplyr::group_by(de_class) |&gt;
    dplyr::mutate(prop = n / sum(n)) |&gt;
    dplyr::ungroup() |&gt;
    dplyr::mutate(
      label = paste0(cog, ": ", COG_LABELS[cog]),
      de_class = factor(de_class, levels = c("up", "background", "down")))

  ## keep only categories with enough tested-gene representation
  keep_cogs &lt;- cog_counts |&gt;
